PROGRAM ST_P01_KRETSKORT
VAR
    steg    : INT := 0;
    tmrFix  : TON;
END_VAR

tmrFix(IN := (steg = 3), PT := T#2000ms);

IF NOT EMG_OK OR NOT AIR_OK THEN
    ST100_RB_START := FALSE;
    ST100_VAC_ON   := FALSE;
    steg := 0;
ELSE
    CASE steg OF
        0:
            ST100_RB_START := FALSE;
            ST100_VAC_ON   := FALSE;
            IF EMG_OK AND AIR_OK AND ST100_KLT_PRS THEN
                steg := 1;
            END_IF;
        1:
            ST100_VAC_ON := TRUE;
            IF ST100_VAC_OK AND ST100_VAC_PRESS >= 45.0 AND ST100_VAC_PRESS <= 80.0 THEN
                steg := 2;
            END_IF;
        2:
            ST100_RB_START := TRUE;
            IF ST100_RB_DONE THEN
                ST100_RB_START := FALSE;
                steg := 3;
            END_IF;
        3:
            IF ST100_FIX_PRS THEN
                ST100_VAC_ON := FALSE;
                steg := 4;
            ELSIF tmrFix.Q THEN
                steg := 9;
            END_IF;
        4:
            IF NOT ST100_VAC_OK THEN
                steg := 0;
            END_IF;
        9:
            ST100_RB_START := FALSE;
    END_CASE;
END_IF;
END_PROGRAM

